def brute_force(target: List[int]) -> int:
    cur = [0] * len(target)
    ops = 0
    while True:
        i, n = 0, len(target)
        # find the first position still below target
        while i < n and cur[i] >= target[i]:
            i += 1
        if i == n:
            return ops
        # extend the stroke across the longest run of still-short positions
        while i < n and cur[i] < target[i]:
            cur[i] += 1
            i += 1
        ops += 1

