def brute_force(l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
    def to_int(node):
        n, place = 0, 1
        while node:
            n += node.val * place
            place *= 10
            node = node.next
        return n
    total = to_int(l1) + to_int(l2)
    return build([int(c) for c in str(total)[::-1]])
